class FormatTimestampTests(unittest.TestCase):
    def test_analytics_converts_to_shanghai(self):
        self.assertEqual(format_timestamp("2024-01-15T16:30:00+00:00", "analytics"), "2024-01-16 00:30")

    def test_public_api_normalizes_to_utc(self):
        self.assertEqual(format_timestamp("2024-01-16T00:30:00+08:00", "public_api"), "2024-01-15 16:30")

    def test_z_suffix(self):
        self.assertEqual(format_timestamp("2024-01-15T16:30:45Z", "public_api"), "2024-01-15 16:30")

    def test_timezone_is_required(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-15T16:30:00", "public_api")

    def test_unknown_target(self):
        with self.assertRaises(ValueError):
            format_timestamp("not-a-timestamp", "internal")

